#!/usr/bin/env python3
"""Write NOTICE: the third-party material in this repository, its source, licence and commit.

  python3 .github/scripts/notice.py           write NOTICE
  python3 .github/scripts/notice.py --check   exit 1 if NOTICE differs from what the sources give

Generated from the records that already say where each file came from: corpus/manifest.json (every
entry's `source`) and schema/SOURCE (the stellar-xdr tags and commits). Run from the repository root.
"""
import json
import sys
from collections import defaultdict

LICENCES = {
    "stellar/stellar-xdr": "Apache License 2.0",
    "stellar/stellar-core": "Apache License 2.0 (its COPYING file)",
    "stellar/stellar-docs": "Apache License 2.0",
}


def render():
    entries = json.load(open("corpus/manifest.json"))["entries"]
    by_kind = defaultdict(list)
    for e in entries:
        by_kind[e["source"]["kind"]].append(e)
    L = ["ShapeCov", "",
         "ShapeCov is licensed under the Apache License 2.0 (LICENSE). It includes material from the sources",
         "below, each under its own terms. This file is generated by .github/scripts/notice.py from",
         "corpus/manifest.json and schema/SOURCE; do not edit it by hand.", ""]

    L += ["1. stellar/stellar-xdr, https://github.com/stellar/stellar-xdr, %s." % LICENCES["stellar/stellar-xdr"],
          "   The XDR definitions (.x files), unmodified:"]
    for line in open("schema/SOURCE"):
        parts = line.split()
        if len(parts) >= 4:
            L.append("   - schema/%s from tag %s, commit %s" % (parts[0], parts[2], parts[3]))
    L.append("")

    golden = by_kind.get("stellar_core_golden", [])
    commits = sorted({e["source"]["stellar_core_commit"] for e in golden})
    L += ["2. stellar/stellar-core, https://github.com/stellar/stellar-core, %s." % LICENCES["stellar/stellar-core"],
          "   %d corpus entries are records copied byte for byte from its golden LedgerCloseMeta files" % len(golden),
          "   (test-lcm-current), at commit %s:" % ", ".join(commits)]
    for e in sorted(golden, key=lambda x: x["id"]):
        s = e["source"]
        L.append("   - corpus/%s: %s, record %s" % (e["file"], s["golden_file"], s["record"]))
    L.append("")

    L += ["3. stellar/stellar-docs, https://github.com/stellar/stellar-docs, %s." % LICENCES["stellar/stellar-docs"],
          "   guide/stellar-docs/prettierrc.cjs is copied from that repository's prettier configuration, so the",
          "   guide's page is formatted as developers.stellar.org formats its own pages.", ""]

    network = by_kind.get("network_ledger", [])
    sources = sorted({e["source"].get("retrieved_from", "").split("/v1")[0] for e in network})
    L += ["4. Stellar network ledger data. %d corpus entries are ledgers of the public Stellar networks," % len(network),
          "   unmodified, retrieved from Stellar's public ledger archive (%s):" % ", ".join(s for s in sources if s)]
    for e in sorted(network, key=lambda x: (x["source"]["network"], x["source"]["ledger_seq"])):
        L.append("   - corpus/%s: %s ledger %d" % (e["file"], e["source"]["network"], e["source"]["ledger_seq"]))
    L.append("")

    local = by_kind.get("local_stellar_core", [])
    generated = by_kind.get("generated", [])
    L += ["Not third-party: %d corpus entries are ledgers that ShapeCov's own scenarios (tools/localcore.py)" % len(local),
          "made by running stellar-core's published images on a private standalone network, and %d are values"
          % len(generated),
          "ShapeCov generated (tools/encode.py from corpus/values/).", ""]
    return "\n".join(L)


def main():
    text = render()
    if "--check" in sys.argv[1:]:
        try:
            current = open("NOTICE").read()
        except FileNotFoundError:
            current = ""
        if current != text:
            print("NOTICE differs from corpus/manifest.json and schema/SOURCE; run python3 .github/scripts/notice.py")
            return 1
        print("NOTICE OK")
        return 0
    with open("NOTICE", "w") as f:
        f.write(text)
    print("wrote NOTICE")
    return 0


if __name__ == "__main__":
    sys.exit(main())
